import { NextRequest, NextResponse } from 'next/server';
import {
  ActivityImportValidationError,
  MAX_ACTIVITY_FILE_SIZE,
  readActivityData,
  validateActivityImport,
  writeActivityData,
} from '@/lib/activityData';
import { isAdminRequest } from '@/lib/adminSession';

export const runtime = 'nodejs';

function errorResponse(
  status: number,
  code: string,
  error: string,
  details?: Array<{ path: string; message: string }>,
) {
  return NextResponse.json({ success: false, code, error, details }, { status });
}

function describeJsonError(error: SyntaxError, source: string) {
  const positionMatch = error.message.match(/position\s+(\d+)/i);
  if (!positionMatch) return error.message;

  const position = Number(positionMatch[1]);
  const beforeError = source.slice(0, position);
  const line = beforeError.split('\n').length;
  const lastLineBreak = beforeError.lastIndexOf('\n');
  const column = position - lastLineBreak;
  return `${line}행 ${column}열 부근의 JSON 문법을 확인해 주세요. (${error.message})`;
}

export async function POST(request: NextRequest) {
  if (!isAdminRequest(request)) {
    return errorResponse(401, 'UNAUTHORIZED', '관리자 인증이 만료되었습니다. 다시 로그인해 주세요.');
  }

  const contentLength = Number(request.headers.get('content-length'));
  if (Number.isFinite(contentLength) && contentLength > MAX_ACTIVITY_FILE_SIZE + 64 * 1024) {
    return errorResponse(413, 'FILE_TOO_LARGE', '파일 크기는 2MB 이하여야 합니다.');
  }

  try {
    const formData = await request.formData();
    const uploadedFile = formData.get('file');

    if (!(uploadedFile instanceof File)) {
      return errorResponse(400, 'FILE_REQUIRED', '업로드할 activity.json 파일을 선택해 주세요.');
    }
    if (!uploadedFile.name.toLowerCase().endsWith('.json')) {
      return errorResponse(400, 'INVALID_FILE_TYPE', '확장자가 .json인 파일만 업로드할 수 있습니다.');
    }
    if (uploadedFile.size === 0) {
      return errorResponse(400, 'EMPTY_FILE', '선택한 파일이 비어 있습니다.');
    }
    if (uploadedFile.size > MAX_ACTIVITY_FILE_SIZE) {
      return errorResponse(413, 'FILE_TOO_LARGE', '파일 크기는 2MB 이하여야 합니다.');
    }

    const source = (await uploadedFile.text()).replace(/^\uFEFF/, '');
    let parsed: unknown;
    try {
      parsed = JSON.parse(source);
    } catch (error) {
      const message = error instanceof SyntaxError
        ? describeJsonError(error, source)
        : 'JSON 문법을 해석하지 못했습니다.';
      return errorResponse(
        400,
        'INVALID_JSON',
        'JSON 문법이 올바르지 않습니다.',
        [{ path: '$', message }],
      );
    }

    const imported = validateActivityImport(parsed);
    const currentData = await readActivityData();
    const newData = {
      activities: imported.activities,
      dashboardTitle: imported.dashboardTitle ?? currentData.dashboardTitle,
      visitorCount: currentData.visitorCount,
      lastUpdated: new Date().toISOString(),
    };

    await writeActivityData(newData, { createBackup: true });

    return NextResponse.json({
      success: true,
      importedCount: newData.activities.length,
      normalizedLegacyStatuses: imported.normalizedLegacyStatuses,
      backupCreated: true,
      data: newData,
    });
  } catch (error) {
    if (error instanceof ActivityImportValidationError) {
      return errorResponse(400, 'INVALID_SCHEMA', error.message, error.issues);
    }

    if (error instanceof TypeError) {
      return errorResponse(
        400,
        'INVALID_FORM_DATA',
        '파일 업로드 요청 형식이 올바르지 않습니다.',
        [{ path: 'file', message: error.message }],
      );
    }

    console.error('POST /api/activities/import failed:', error);
    return errorResponse(500, 'STORAGE_ERROR', '검증은 완료되었지만 서버에 activity.json을 저장하지 못했습니다.');
  }
}
