/**
 * 인식하지 못한 PUT 은 400 이어야 하고, 저장된 활동·lastUpdated 를 건드리지 않아야 한다.
 * 400 이어도 lastUpdated 가 바뀌면 "조용히 다시 저장" 하고 있다는 뜻이다.
 */
async function expectRejectedAndUnchanged(request: APIRequestContext, body: unknown) {
  const before = await readData(request);

  const response = await request.put('/api/activities', { data: body });
  expect(response.status(), await response.text()).toBe(400);
  const result = await response.json() as { error?: string };
  expect(typeof result.error).toBe('string');
  expect(result.error).not.toBe('');

  const after = await readData(request);
  expect(after.activities).toEqual(before.activities);
  expect(after.lastUpdated).toBe(before.lastUpdated);
}

test('인식할 수 있는 변경 지시도 dashboardTitle 도 없는 PUT 은 400 이고 저장 내용이 그대로다', async ({ request }) => {
  await expectRejectedAndUnchanged(request, { foo: 'bar' });
});

test('빈 객체 PUT 도 400 이고 저장 내용이 그대로다', async ({ request }) => {
  await expectRejectedAndUnchanged(request, {});
});

test('action 은 알지만 인자가 계약에 맞지 않는 PUT 은 400 이다', async ({ request }) => {
  // parentId 가 문자열·null 이 아니다
  await expectRejectedAndUnchanged(request, { action: 'add', parentId: 5 });
  // direction 이 up/down 이 아니다
  await expectRejectedAndUnchanged(request, { action: 'move', targetId: 'root', direction: 'left' });
  // targetId 가 없다
  await expectRejectedAndUnchanged(request, { action: 'delete' });
  // 알 수 없는 action
  await expectRejectedAndUnchanged(request, { action: 'rename', targetId: 'root' });
});

